SELECT id, symbol, interval_code, candle_open_time, UNIX_TIMESTAMP(candle_open_time) AS candle_open_epoch, generated_at, UNIX_TIMESTAMP(generated_at) AS gen_epoch, created_at, UNIX_TIMESTAMP(created_at) AS created_epoch, signal_mode, data_quality_valid, decision, original_decision, final_entry_allowed, primary_blocking_stage, total_score, confidence_score, effective_confidence_score, selected_strategy, market_regime, confirmed_regime, latest_price, stop_loss, take_profit, atr_at_signal, atr_percent, risk_reward_ratio, atr_entry_type, atr_immediate_entry_allowed, atr_recommended_position_percent, confluence_status, confluence_higher_decision, btc_context_status, btc_context_entry_allowed, liquidity_status, derivatives_status, entry_authority FROM crypto_ai.trade_signal WHERE id IN (156723,159408,165412,167668,171589,176710,159285,159407,165415,176655) ORDER BY id;